const r=require('./round-fixes.js');
const A=q=>r.verifiedRoundAnswer(r.normalizeQuestion(q),{});
const yes=[
 ['協會解散了還可以再成立嗎','第8條'],['社團解散後要重新成立怎麼辦','重新'],
 ['解散大會可以委託別人出席嗎','第42條'],['解散投票人不能到可以請人代理嗎','代理一人'],
 ['沒有人要當理事了協會可以直接不做嗎','不能一直放著'],['協會乾脆不辦了可以嗎','第59條'],
 ['協會解散時還有債務怎麼辦','先清償債務'],['解散了但是欠錢還不出來怎麼辦','清算'],
 ['解散跟廢止立案有什麼不一樣','第58條'],['解散和廢止許可的差別','第59條'],
 ['解散後會員還要繳會費嗎','查不到'],
 ['協會解散要不要登報','沒有寫解散要登報'],['解散要公告嗎','總機'],
 ['解散清算完要不要再報縣府','第27條'],['清算結束後要通知縣府嗎','查不到明文'],
 ['解散要報給誰','社會處'],['協會要解散先向誰報','縣政府'],
 ['解散要找誰來清算','清算人'],['清算誰負責','第27條'],
 ['解散決議不夠人數怎麼辦','三分之二'],['解散案沒有過怎麼辦','協會繼續存在'],
 ['理事長可以自己決定把協會解散嗎','不可以'],
 ['解散時有補助款還沒核銷怎麼辦','補助'],
];
const no=['合作社解散怎麼辦','社區發展協會解散後財產歸誰','解散要送哪些報表','解散要多少人同意','協會解散後剩餘財產歸誰','理事長可以自行決定活動嗎','協會會員要退會怎麼辦','補助款核銷要準備什麼','協會可以直接領現金嗎','公會解散清算人是誰'];
const mine=/(再成立|解散大會可以委託|不能直接不做|解散時還有債務|解散和廢止許可|解散後會員還要不要|要不要登報|清算完要不要|解散要報給縣|解散案人數不夠|補助款還沒核銷)/;
let bad=0;
yes.forEach(([q,e])=>{const a=A(q);const txt=a&&a.title?(a.title+a.summary):'';if(!txt.includes(e)||!a.direct){bad++;console.log('✗',q,a&&(a.title||a))}});
no.forEach(q=>{const a=A(q);if(a&&a.title&&mine.test(a.title)){bad++;console.log('✗誤觸',q,a.title)}});
console.log(bad?'失敗 '+bad:'全部通過');process.exit(bad?1:0);
